CREATE TABLE users(id INTEGER PRIMARY KEY, login TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('ADMIN','TEACHER')), active INTEGER NOT NULL CHECK(active IN(0,1)), password_hash TEXT NOT NULL, password_version INTEGER NOT NULL DEFAULT 1, failed_attempts INTEGER NOT NULL DEFAULT 0, locked_until TEXT);
CREATE TABLE study_groups(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE students(id INTEGER PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES study_groups(id), number TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE study_periods(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN(0,1)), CHECK(starts_on<=ends_on));
CREATE TABLE teaching_assignments(id INTEGER PRIMARY KEY, teacher_id INTEGER NOT NULL REFERENCES users(id), subject_id INTEGER NOT NULL REFERENCES subjects(id), group_id INTEGER NOT NULL REFERENCES study_groups(id), period_id INTEGER NOT NULL REFERENCES study_periods(id), active INTEGER NOT NULL CHECK(active IN(0,1)), UNIQUE(teacher_id,subject_id,group_id,period_id));
CREATE INDEX idx_assignments_teacher ON teaching_assignments(teacher_id,subject_id,active);
CREATE INDEX idx_students_group ON students(group_id,active);
ALTER TABLE questions ADD COLUMN reviewed_at TEXT;
UPDATE questions SET reviewed_at=(SELECT substr(saved_at,1,10) FROM question_revisions r WHERE r.question_id=questions.id AND r.revision_no=questions.current_revision);
ALTER TABLE audit_log ADD COLUMN subject_id INTEGER REFERENCES subjects(id);
ALTER TABLE audit_log ADD COLUMN result TEXT NOT NULL DEFAULT 'SUCCESS';
UPDATE audit_log SET subject_id=object_id WHERE object_type='subject';
UPDATE audit_log SET subject_id=(SELECT subject_id FROM topics WHERE id=audit_log.object_id) WHERE object_type='topic';
UPDATE audit_log SET subject_id=(SELECT t.subject_id FROM questions q JOIN topics t ON t.id=q.topic_id WHERE q.id=audit_log.object_id) WHERE object_type='question';
CREATE TABLE ranking_profiles(id INTEGER PRIMARY KEY, subject_id INTEGER NOT NULL REFERENCES subjects(id), name TEXT NOT NULL COLLATE NOCASE, version INTEGER NOT NULL CHECK(version>0), formula TEXT NOT NULL CHECK(formula='rank-v1'), target INTEGER NOT NULL CHECK(target BETWEEN 1 AND 5), weight_i REAL NOT NULL CHECK(weight_i>=0), weight_f REAL NOT NULL CHECK(weight_f>=0), weight_d REAL NOT NULL CHECK(weight_d>=0), weight_a REAL NOT NULL CHECK(weight_a>=0), weight_e REAL NOT NULL CHECK(weight_e>=0), horizon INTEGER NOT NULL CHECK(horizon>0), minimum_samples INTEGER NOT NULL CHECK(minimum_samples>0), warning_threshold REAL NOT NULL CHECK(warning_threshold BETWEEN 0 AND 4), saved_at TEXT NOT NULL, UNIQUE(subject_id,name,version), CHECK(weight_i+weight_f+weight_d+weight_a+weight_e>0));
INSERT INTO ranking_profiles(subject_id,name,version,formula,target,weight_i,weight_f,weight_d,weight_a,weight_e,horizon,minimum_samples,warning_threshold,saved_at) SELECT id,'Основной',1,'rank-v1',3,0.30,0.25,0.20,0.15,0.10,365,10,1.5,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM subjects;
CREATE TABLE ranking_observations(id INTEGER PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, question_id INTEGER NOT NULL, revision INTEGER NOT NULL, occurred_on TEXT NOT NULL, uses INTEGER NOT NULL CHECK(uses>=0), attempts INTEGER NOT NULL CHECK(attempts>=0), ratio_sum REAL NOT NULL CHECK(ratio_sum>=0 AND ratio_sum<=attempts), source TEXT NOT NULL CHECK(source IN('MANUAL','EXAM')), synthetic INTEGER NOT NULL CHECK(synthetic IN(0,1)), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision_no));
CREATE INDEX idx_observations_question ON ranking_observations(question_id,occurred_on,revision);
